mapper.select:
SELECT id, chat_room_id, sender_id, message_type, content, file_url, is_read, created_at
  FROM chat_messages
 WHERE chat_room_id = #{chatRoomId}
 ORDER BY id ASC
 LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE chat_messages
   SET is_read = 1
 WHERE chat_room_id = #{chatRoomId}
   AND sender_id != #{readerId}
   AND is_read = 0

mapper.select:
SELECT COUNT(1) FROM chat_messages
 WHERE chat_room_id = #{chatRoomId}
   AND sender_id != #{readerId}
   AND is_read = 0
